import{_ as s,o as n,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const u=JSON.parse('{"title":"项目二：生成一份 PPT 报告（进阶级）","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-5/project-2.md","filePath":"modules/module-5/project-2.md"}'),p={name:"modules/module-5/project-2.md"};function l(i,a,o,d,c,r){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="项目二-生成一份-ppt-报告-进阶级" tabindex="-1">项目二：生成一份 PPT 报告（进阶级） <a class="header-anchor" href="#项目二-生成一份-ppt-报告-进阶级" aria-label="Permalink to &quot;项目二：生成一份 PPT 报告（进阶级）&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：学会让 Codex 联网搜索资料并生成演示文稿<br> ⏱️ <strong>预计时长</strong>：30 分钟<br> 🎯 <strong>学到的能力</strong>：联网检索、内容整理、技能调用</p></blockquote><hr><h2 id="一、任务描述" tabindex="-1">一、任务描述 <a class="header-anchor" href="#一、任务描述" aria-label="Permalink to &quot;一、任务描述&quot;">​</a></h2><p>让 Codex 根据网上资料生成一份主题演示文稿。</p><hr><h2 id="二、操作步骤" tabindex="-1">二、操作步骤 <a class="header-anchor" href="#二、操作步骤" aria-label="Permalink to &quot;二、操作步骤&quot;">​</a></h2><h3 id="步骤-1-选择主题" tabindex="-1">步骤 1：选择主题 <a class="header-anchor" href="#步骤-1-选择主题" aria-label="Permalink to &quot;步骤 1：选择主题&quot;">​</a></h3><p>选择一个你感兴趣的话题，比如：</p><ul><li>&quot;2026 年 AI 发展趋势&quot;</li><li>&quot;远程办公的最佳实践&quot;</li><li>&quot;健康饮食指南&quot;</li><li>&quot;新能源汽车市场现状&quot;</li></ul><h3 id="步骤-2-让-codex-生成大纲" tabindex="-1">步骤 2：让 Codex 生成大纲 <a class="header-anchor" href="#步骤-2-让-codex-生成大纲" aria-label="Permalink to &quot;步骤 2：让 Codex 生成大纲&quot;">​</a></h3><p>打开 Codex，输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我做一个关于&quot;[你的主题]&quot;的演示文稿，要求：</span></span>
<span class="line"><span>1. 10-15 页左右</span></span>
<span class="line"><span>2. 包含封面、目录、主要观点分析、案例、总结</span></span>
<span class="line"><span>3. 每页要有标题和 3-5 个要点</span></span>
<span class="line"><span>4. 风格要简洁专业</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先给我一个大纲，等我确认后再开始制作。</span></span></code></pre></div><h3 id="步骤-3-审查大纲" tabindex="-1">步骤 3：审查大纲 <a class="header-anchor" href="#步骤-3-审查大纲" aria-label="Permalink to &quot;步骤 3：审查大纲&quot;">​</a></h3><p>Codex 会生成类似这样的结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>📊 [主题] 演示文稿大纲</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 1 页：封面</span></span>
<span class="line"><span>- 标题、副标题、日期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第 2 页：目录</span></span>
<span class="line"><span>- 背景介绍</span></span>
<span class="line"><span>- 核心趋势</span></span>
<span class="line"><span>- 案例分析</span></span>
<span class="line"><span>- 未来展望</span></span>
<span class="line"><span>- 总结</span></span>
<span class="line"><span></span></span>
<span class="line"><span>...（更多页面）</span></span></code></pre></div><p>检查大纲是否覆盖了你关心的所有方面，如有需要可以调整。</p><h3 id="步骤-4-让-codex-联网搜索并填充内容" tabindex="-1">步骤 4：让 Codex 联网搜索并填充内容 <a class="header-anchor" href="#步骤-4-让-codex-联网搜索并填充内容" aria-label="Permalink to &quot;步骤 4：让 Codex 联网搜索并填充内容&quot;">​</a></h3><p>确认大纲后，输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>大纲没问题，请开始制作。</span></span>
<span class="line"><span>注意：</span></span>
<span class="line"><span>1. 联网搜索最新的资料来填充内容</span></span>
<span class="line"><span>2. 每个观点都要有数据或案例支撑</span></span>
<span class="line"><span>3. 引用来源要标注清楚</span></span>
<span class="line"><span>4. 使用专业的商务风格</span></span></code></pre></div><h3 id="步骤-5-审查并微调" tabindex="-1">步骤 5：审查并微调 <a class="header-anchor" href="#步骤-5-审查并微调" aria-label="Permalink to &quot;步骤 5：审查并微调&quot;">​</a></h3><p>Codex 完成后，审查生成的内容：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我检查一下：</span></span>
<span class="line"><span>1. 数据是否最新？</span></span>
<span class="line"><span>2. 有没有过时的信息？</span></span>
<span class="line"><span>3. 语言是否通顺？</span></span>
<span class="line"><span>4. 格式是否统一？</span></span></code></pre></div><p>然后根据 Codex 的建议进行微调。</p><hr><h2 id="三、进阶技巧" tabindex="-1">三、进阶技巧 <a class="header-anchor" href="#三、进阶技巧" aria-label="Permalink to &quot;三、进阶技巧&quot;">​</a></h2><h3 id="添加图表" tabindex="-1">添加图表 <a class="header-anchor" href="#添加图表" aria-label="Permalink to &quot;添加图表&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在&quot;市场规模&quot;这一页，帮我生成一个柱状图来展示过去 5 年的数据变化</span></span></code></pre></div><h3 id="转换语言" tabindex="-1">转换语言 <a class="header-anchor" href="#转换语言" aria-label="Permalink to &quot;转换语言&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把这份演示文稿翻译成英文版本</span></span></code></pre></div><h3 id="导出为不同格式" tabindex="-1">导出为不同格式 <a class="header-anchor" href="#导出为不同格式" aria-label="Permalink to &quot;导出为不同格式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>把内容保存为 Markdown 格式的文件，方便我后续编辑</span></span></code></pre></div><hr><h2 id="四、本节小结" tabindex="-1">四、本节小结 <a class="header-anchor" href="#四、本节小结" aria-label="Permalink to &quot;四、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>学到的能力</th><th>具体说明</th></tr></thead><tbody><tr><td>联网检索</td><td>让 Codex 搜索最新资料</td></tr><tr><td>内容整理</td><td>从搜索结果中提取关键信息</td></tr><tr><td>技能调用</td><td>使用 PPT 生成技能</td></tr><tr><td>迭代优化</td><td>通过追问不断完善结果</td></tr></tbody></table><hr><h2 id="五、下一步" tabindex="-1">五、下一步 <a class="header-anchor" href="#五、下一步" aria-label="Permalink to &quot;五、下一步&quot;">​</a></h2><p><a href="./project-3.html">→ 项目三：做一个简单网页</a></p>`,38)])])}const b=s(p,[["render",l]]);export{u as __pageData,b as default};
